"""Generated by Codex. Verify detection and redaction using synthetic credentials."""
import os
from pathlib import Path
import subprocess
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[2]


class SecretScanTests(unittest.TestCase):
    def test_directory_detection_and_redaction(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            sample = root / 'settings.txt'
            sample.write_text('API_KEY=\n')
            command = ['bash', str(ROOT / 'script/ci/check_secrets.sh'), directory]
            clean = subprocess.run(command, capture_output=True, text=True)
            self.assertEqual(clean.returncode, 0, clean.stdout + clean.stderr)
            # Construct an invalid, synthetic token so no credential is committed.
            token = 'gh' + 'p_' + '0123456789abcdef' * 2 + 'abcd'
            sample.write_text('GITHUB_TOKEN=' + token + '\n')
            leaked = subprocess.run(command, capture_output=True, text=True)
            self.assertEqual(leaked.returncode, 1)
            self.assertNotIn(token, leaked.stdout + leaked.stderr)

    def test_deleted_secret_is_detected_in_history(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            env = dict(os.environ, GIT_CONFIG_COUNT='0',
                       GIT_AUTHOR_NAME='Scanner Test', GIT_AUTHOR_EMAIL='test@example.invalid',
                       GIT_COMMITTER_NAME='Scanner Test', GIT_COMMITTER_EMAIL='test@example.invalid')

            def git(*args):
                subprocess.run(['git', *args], cwd=root, env=env, check=True,
                               capture_output=True)

            git('init')
            sample = root / 'settings.txt'
            token = 'gh' + 'p_' + '0123456789abcdef' * 2 + 'abcd'
            sample.write_text('GITHUB_TOKEN=' + token + '\n')
            git('add', '.')
            git('-c', 'core.hooksPath=/dev/null', 'commit', '-m', 'Synthetic fixture')
            sample.unlink()
            git('add', '-u')
            git('-c', 'core.hooksPath=/dev/null', 'commit', '-m', 'Remove fixture')
            result = subprocess.run([
                os.environ.get('GITLEAKS_BIN', 'gitleaks'), 'git',
                '--config', str(ROOT / '.gitleaks.toml'), '--redact=100',
                '--no-banner', '--ignore-gitleaks-allow', '--log-opts=--all', str(root),
            ], capture_output=True, text=True)
            self.assertEqual(result.returncode, 1)
            self.assertNotIn(token, result.stdout + result.stderr)


if __name__ == '__main__':
    unittest.main()
